//! Differential test: our unified hunks against GNU diff 3.10's, case for case.
//!
//! WHY THIS SUITE EXISTS. Every other test in this crate asserts a rule
//! somebody wrote down. This one asserts the whole alignment against the tool
//! the builtin exists to replace, over a corpus wide enough to catch the cases
//! nobody thought to write down: blank lines that moved, adjacent swaps,
//! duplicate runs, moved blocks, files with no trailing newline, CRLF, and
//! thirty pseudo-random pairs and forty wider ones drawn from an alphabet
//! chosen to make ties
//! common. Ties are where two implementations of an optimal diff legitimately
//! disagree, and a divergence there is invisible until somebody compares.
//!
//! HOW THE FIXTURE WAS BUILT. `diff -u <flags> A B` was run for every pair and
//! every flag combination below, and its output was captured verbatim; the
//! `---`/`+++` header is dropped because it carries timestamps and this crate
//! writes labels its caller chooses, so what is compared is the part that
//! describes the ALIGNMENT: the `@@` ranges and the `-`/`+`/` ` lines. The exit
//! status is compared too, through `differs`, because under `-B` a pair can
//! have differing bytes and no surviving hunk.
//!
//! A CASE THAT FAILS HERE IS A FINDING, not a fixture to adjust. All 784 cases
//! agree and no case carries a `divergence` note. The mechanism stays because
//! it is what proved the fixes were fixes: a case that is knowingly different
//! records the reason and its ledger row in `divergence`, and the suite fails
//! when such a case starts AGREEING as well, so a note cannot outlive the
//! difference it describes. That is how the last 10 were found to be closed by
//! porting GNU's discard pass, how `wide-ws-06 [-i]` was found to be closed
//! before them, and how the 33 of the original 464 were.
//!
//! HOW THE FIXTURE MUST BE CAPTURED. `diff -U N` and never `diff -u -U N`: GNU
//! resolves the context size as the MAXIMUM of every specification, and a bare
//! `-u` beside an explicit `-U` contributes 3, so `diff -u -U 0` prints three
//! lines of context and not zero. The first capture of the `-U 0` and `-U 1`
//! cases made that mistake and produced 13 bogus disagreements.

use veyyon_diff_kernel::{Ignore, Unified};

/// One pair, one flag combination, and what GNU printed for it.
struct Case {
	/// The pair's name, so a failure says which shape broke.
	name:       &'static str,
	/// The flags as written on the `diff` command line, for the failure message.
	flags:      &'static str,
	old:        &'static str,
	new:        &'static str,
	/// `-U N`, defaulting to GNU's 3.
	context:    usize,
	/// The `Ignore` fields the flags set, by field name.
	ignore:     &'static [&'static str],
	/// Whether GNU exited 1.
	differs:    bool,
	/// GNU's output from the first `@@` on, or empty when it printed nothing.
	hunks:      &'static str,
	/// Set when OUR answer is knowingly different, with the reason.
	divergence: Option<&'static str>,
}

/// The flag names map to `Ignore` fields by hand, so a typo in the fixture is a
/// panic here rather than a silently unset flag.
fn ignore_from(names: &[&str]) -> Ignore {
	let mut ignore = Ignore::default();
	for name in names {
		match *name {
			"case" => ignore.case = true,
			"all_space" => ignore.all_space = true,
			"space_change" => ignore.space_change = true,
			"trailing_space" => ignore.trailing_space = true,
			"tab_expansion" => ignore.tab_expansion = true,
			"blank_lines" => ignore.blank_lines = true,
			other => panic!("unknown ignore flag in the fixture: {other}"),
		}
	}
	ignore
}

/// What this crate prints for one case, from the first `@@` on.
fn our_hunks(case: &Case) -> (bool, String) {
	let diff = Unified::compute(case.old, case.new, case.context, ignore_from(case.ignore));
	let mut out = Vec::new();
	diff
		.write(&mut out, "A", "B")
		.expect("writing to a Vec cannot fail");
	let text = String::from_utf8(out).expect("the fixture is UTF-8");
	let mut hunks = String::new();
	for line in text.lines().skip_while(|line| !line.starts_with("@@")) {
		hunks.push_str(line);
		hunks.push('\n');
	}
	(diff.differs(), hunks)
}

/// Every case, compared in one test so a run reports the whole divergence list
/// rather than the first line of it.
#[test]
fn our_hunks_match_gnu_diff_case_for_case() {
	let mut failures = Vec::new();
	for case in CASES {
		let (differs, hunks) = our_hunks(case);
		let matched = differs == case.differs && hunks == case.hunks;
		match (matched, case.divergence) {
			(true, None) => {},
			(true, Some(reason)) => failures.push(format!(
				"{} [{}]: agrees with GNU now, so the exception is stale and has to go: {reason}",
				case.name, case.flags
			)),
			(false, Some(_)) => {},
			(false, None) => failures.push(format!(
				"{} [{}]:\n  ours:  differs={differs} {hunks:?}\n  GNU:   differs={} {:?}",
				case.name, case.flags, case.differs, case.hunks
			)),
		}
	}
	assert!(
		failures.is_empty(),
		"{} of {} cases disagree with GNU diff 3.10:\n{}",
		failures.len(),
		CASES.len(),
		failures.join("\n")
	);
}

